// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guess) public {
        address player = address(0xBEEF);
        vm.deal(player, 2 ether);

        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        uint256 committedBlock = block.number + 1;
        vm.roll(committedBlock + 1);
        vm.prank(player);
        c.settle();

        bool secondSettleReverted;
        vm.prank(player);
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }
        assertTrue(secondSettleReverted);
    }
}
